// TestSchemelessUserinfoRedactionShapes covers the address shapes the
// redacted rendering must take: a username-only userinfo, an empty
// password, colons in the password, multiple '@' bytes (everything before
// the authority's last '@' is credential), a username reduced to an empty
// authority, and no base path. Every one renders as "//***@...".
func TestSchemelessUserinfoRedactionShapes(t *testing.T) {
	cases := []struct {
		name     string
		upstream string
		shown    string
		hidden   []string
	}{
		{"username and password", "//alice:secret@api.internal:8080/v1", "//***@api.internal:8080/v1", []string{"alice", "secret"}},
		{"username only", "//alice@api.internal/v1", "//***@api.internal/v1", []string{"alice"}},
		{"empty password", "//alice:@api.internal/v1", "//***@api.internal/v1", []string{"alice"}},
		{"colons in password", "//alice:s3:cr3t@api.internal/v1", "//***@api.internal/v1", []string{"alice", "s3:cr3t"}},
		{"multiple at signs in authority", "//al@ice:p%40w@api.internal/v1", "//***@api.internal/v1", []string{"al@ice", "p%40w"}},
		{"userinfo reduced to empty authority", "//svc@/v1", "//***@/v1", []string{"svc"}},
		{"no base path", "//alice:secret@api.internal", "//***@api.internal", []string{"alice", "secret"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			// These addresses parse; they fail the missing-scheme rule. The
			// empty-authority case fails the missing-host rule first, which is
			// the same selection order an http:// spelling uses.
			cfg, f := parseSchemelessRoute(t, tc.upstream)
			assertCredentialFreeUserinfoReason(t, f, cfg, "route 1", "api", tc.shown, tc.hidden)
		})
	}
}

